formulas.expression:
VALUE(
  LEFT(
    RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("ACR Check Reading:", {!OutputFormatFetched}) - LEN("ACR Check Reading:")),
    FIND("<br>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("ACR Check Reading:", {!OutputFormatFetched}) - LEN("ACR Check Reading:"))) - 1
  )
)

VALUE(
  LEFT(
    RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("BIOS battery:", {!OutputFormatFetched}) - LEN("BIOS battery:")),
    FIND("</b>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("BIOS battery:", {!OutputFormatFetched}) - LEN("BIOS battery:"))) - 1
  )
)

VALUE(
  LEFT(
    RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("SNR Check Reading:", {!OutputFormatFetched}) - LEN("SNR Check Reading:")),
    FIND("<br>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("SNR Check Reading:", {!OutputFormatFetched}) - LEN("SNR Check Reading:"))) - 1
  )
)
